import{AGENT_TOOL_NAME,isImplicitAgentToolAvailable}from"#runtime/framework-tools/agent.js";import{composeRuntimeBasePrompt}from"#runtime/prompt/compose.js";const BOOTSTRAP_RUNTIME_MODEL_ID=`eve-bootstrap-model`,BOOTSTRAP_RUNTIME_SYSTEM_PROMPT=`You are the eve bootstrap agent. Be concise, stay grounded in the current conversation, and do not assume tools are available unless the runtime provides them.`;function createResolvedRuntimeTurnAgent(n){let r=n.agent,i=n.tools.some(e=>e.kind===`subagent`||e.kind===`remote`),a=isImplicitAgentToolAvailable({disabledFrameworkTools:r.disabledFrameworkTools,hasAuthoredAgentTool:n.tools.some(t=>t.name===AGENT_TOOL_NAME),nodeId:n.nodeId});return{availableSkills:r.skills.map(e=>({description:e.description,name:e.name})),id:r.config.name,instructions:composeRuntimeBasePrompt({connections:r.connections,instructions:r.instructions,persistentSubagentSessions:r.config.experimental?.subagentPersistentSessions===!0,subagentsAvailable:i||a,toolsAvailable:n.tools.length>0||a,workspaceSpec:r.workspaceSpec}),compactionModel:r.config.compaction?.model,dynamicModel:r.config.dynamicModel,model:r.config.model,nodeId:n.nodeId,outputSchema:r.config.outputSchema,reasoning:r.config.reasoning,tools:[...n.tools],workspaceSpec:r.workspaceSpec}}export{BOOTSTRAP_RUNTIME_MODEL_ID,BOOTSTRAP_RUNTIME_SYSTEM_PROMPT,createResolvedRuntimeTurnAgent};